"""Stateful replay preparation.

A preparation is a path of enabled transitions from the initial state to the
recovered desired state.  Guards are evaluated on the recovered entry inputs
(including the desired state), never on an intermediate simulation state, so
enabled transitions are constant for one record.  Among all usable paths the
minimiser of `(sum of costs, number of commands, command sequence
lexicographically)` is required exactly, and it is found by combining a
reverse Dijkstra on `(cost, commands)` with a forward greedy walk that always
takes the smallest command which still admits an optimal completion.
"""
import heapq

from .errors import InvalidCampaign

_INFINITE = None


class Transition(object):
    """One guarded edge of the state machine."""

    __slots__ = ("source", "target", "command", "cost", "guard", "index")

    def __init__(self, source, target, command, cost, guard, index):
        self.source = source
        self.target = target
        self.command = command
        self.cost = cost
        self.guard = guard
        self.index = index


class Machine(object):
    """The recorded state machine shared by every entry of a campaign."""

    def __init__(self, document):
        if not isinstance(document, dict):
            raise InvalidCampaign("machine must be an object")
        states = document.get("states")
        if not isinstance(states, list) or not states:
            raise InvalidCampaign("machine states expected")
        for state in states:
            if not isinstance(state, str) or not state or not state.isascii() \
                    or not state.isprintable() or len(state) > 64:
                raise InvalidCampaign("state name must be printable ASCII")
        if len(set(states)) != len(states):
            raise InvalidCampaign("duplicate state name")
        self.states = list(states)
        self.initial = document.get("initial")
        if self.initial not in self.states:
            raise InvalidCampaign("unknown initial state")
        self.state_param = document.get("state_param")
        self.message_param = document.get("message_param")
        for name in (self.state_param, self.message_param):
            if not isinstance(name, str) or not name:
                raise InvalidCampaign("machine parameter name expected")
        raw = document.get("transitions")
        if not isinstance(raw, list):
            raise InvalidCampaign("machine transitions must be a list")
        self.transitions = []
        self.commands = []
        pairs = set()
        guards = {}
        self.guard_sources = []
        self.guard_index = []
        for item in raw:
            if not isinstance(item, dict):
                raise InvalidCampaign("transition must be an object")
            source = item.get("from")
            target = item.get("to")
            command = item.get("command")
            cost = item.get("cost")
            guard = item.get("when")
            if source not in self.states or target not in self.states:
                raise InvalidCampaign("transition endpoint is unknown")
            if not isinstance(command, str) or not command or not command.isascii() \
                    or not command.isprintable() or len(command) > 64:
                raise InvalidCampaign("command must be printable ASCII")
            if cost.__class__ is not int or not 1 <= cost <= 65535:
                raise InvalidCampaign("transition cost out of range")
            if guard is not None and not isinstance(guard, list):
                raise InvalidCampaign("transition guard must be a predicate")
            if (source, command) in pairs:
                raise InvalidCampaign("duplicate (from, command) pair")
            pairs.add((source, command))
            key = _guard_key(guard)
            if key not in guards:
                guards[key] = len(self.guard_sources)
                self.guard_sources.append(guard)
            index = len(self.transitions)
            self.transitions.append(
                Transition(source, target, command, cost, guard, index))
            self.guard_index.append(guards[key])
        self.outgoing = {state: [] for state in self.states}
        self.incoming = {state: [] for state in self.states}
        for transition in self.transitions:
            self.outgoing[transition.source].append(transition)
            self.incoming[transition.target].append(transition)
        for state in self.states:
            self.outgoing[state].sort(key=lambda item: item.command)
        self.state_set = set(self.states)

    def prepare(self, desired, enabled):
        """Return `(cost, commands)` for the optimal preamble, or None."""
        if desired not in self.state_set:
            return None
        distances = self._distances(desired, enabled)
        best = distances.get(self.initial)
        if best is None:
            return None
        commands = []
        current = self.initial
        remaining = best
        while current != desired:
            chosen = None
            for transition in self.outgoing[current]:
                if not enabled[transition.index]:
                    continue
                onward = distances.get(transition.target)
                if onward is None:
                    continue
                if (transition.cost + onward[0], 1 + onward[1]) != remaining:
                    continue
                chosen = transition
                break
            if chosen is None:
                return None
            commands.append(chosen.command)
            current = chosen.target
            remaining = distances[current]
        return (best[0], commands)

    def _distances(self, desired, enabled):
        """Minimal `(cost, commands)` from every state to `desired`."""
        distances = {desired: (0, 0)}
        heap = [(0, 0, desired)]
        incoming = self.incoming
        while heap:
            cost, count, state = heapq.heappop(heap)
            if distances.get(state) != (cost, count):
                continue
            for transition in incoming[state]:
                if not enabled[transition.index]:
                    continue
                source = transition.source
                candidate = (cost + transition.cost, count + 1)
                known = distances.get(source)
                if known is None or candidate < known:
                    distances[source] = candidate
                    heapq.heappush(heap, (candidate[0], candidate[1], source))
        return distances


def _guard_key(guard):
    """A structural key so identical guard ASTs are evaluated once per run."""
    return _canonical(guard)


def _canonical(value):
    kind = value.__class__
    if kind is bool:
        return ("b", value)
    if kind is int:
        return ("i", value)
    if kind is str:
        return ("s", value)
    if kind is list:
        return ("l", tuple(_canonical(item) for item in value))
    if kind is dict:
        return ("o", tuple(sorted((key, _canonical(item))
                                  for key, item in value.items())))
    if value is None:
        return ("n",)
    return ("?", repr(value))
